e(9,'',4,4,'Determine','Determine the output produced after execution of mystery(NAMES,3). Show all your working.',C,['B2.4.5'],'B',6,'Call chain3,2,1,0 then prints Kim,Eli,Murali,Zixan; working required for full4.','Trace reveal(["Oak","Pine","Elm"],2), showing the recursive calls and order of printed values.\n\n'+code,pts((1,'Call sequence n=2→1→0.'),(1,'Base call prints Elm.'),(1,'Returning n=1 call prints Pine.'),(1,'Returning n=2 call prints Oak.')),code=code,tests='import io,contextlib\nbuf=io.StringIO()\nwith contextlib.redirect_stdout(buf): reveal(["Oak","Pine","Elm"],2)\nassert buf.getvalue()=="Elm\\nPine\\nOak\\n"',assets=[pageasset('SRC-005',4,'Source name array and recursive pseudocode')],reason='Nonbranching recursion and post-call output retained; Python and different list/index boundary replace old pseudocode.')
